// Kiểm token webhook (tùy chọn) + build prompt skill theo action.
const EXPECTED = $env.BDS_WEBHOOK_TOKEN || '';
const auth = ($input.first().json.headers?.authorization) || '';
if (EXPECTED && auth !== `Bearer ${EXPECTED}`) {
  throw new Error('Unauthorized: sai BDS_WEBHOOK_TOKEN');
}

const body = $input.first().json.body || {};
const action = String(body.action || '');
const accountId = String(body.account_id || '');
const p = body.params || {};

const rule = 'Gặp captcha/checkpoint/đăng nhập lại/cảnh báo bất thường thì trả status="checkpoint". Lỗi khác trả status="error". CHỈ IN JSON, không thêm chữ nào.';

let task;
switch (action) {
  case 'check_phone':
    task = `Trên tài khoản Zalo ${accountId}: mở "Thêm bạn" và tìm theo số ${p.phone}. Nếu hiện hồ sơ người dùng -> has_zalo=true và lấy display_name. Nếu báo không tìm thấy -> has_zalo=false. ${rule} Định dạng: {"status":"ok","data":{"has_zalo":true,"display_name":"..."}}`;
    break;
  case 'add_friend':
    task = `Trên tài khoản Zalo ${accountId}: gửi lời mời kết bạn tới số ${p.phone} kèm lời nhắn: "${p.message}". ${rule} Định dạng: {"status":"ok"}`;
    break;
  case 'send_message':
    task = `Trên tài khoản Zalo ${accountId}: gửi tin nhắn tới số ${p.phone} với nội dung: "${p.message}". ${rule} Định dạng: {"status":"ok"}`;
    break;
  case 'add_group':
    task = `Trên tài khoản Zalo ${accountId}: mời số ${p.phone} vào nhóm ${p.groupId}. ${rule} Định dạng: {"status":"ok"}`;
    break;
  case 'fb_like':
    task = `Trên tài khoản Facebook ${accountId}: mở bài ${p.postId} và bấm Thích. ${rule} Định dạng: {"status":"ok"}`;
    break;
  case 'fb_comment':
    task = `Trên tài khoản Facebook ${accountId}: mở bài ${p.postId} và bình luận ĐÚNG NGUYÊN VĂN (không sửa, không thêm): "${p.text}". ${rule} Định dạng: {"status":"ok"}`;
    break;
  default:
    throw new Error(`action không hợp lệ: ${action}`);
}

return [{ json: { action, accountId, prompt: task, correlation_id: body.correlation_id || '' } }];

// Trích JSON nghiêm ngặt từ câu trả lời agent, chuẩn hóa về {status,data,message}.
const res = $input.first().json || {};

// Tìm text trả lời ở vài field khả dĩ của gateway.
let reply = res.response ?? res.reply ?? res.text ?? res.message ?? res.data?.response ?? res.data?.message ?? '';
if (typeof reply === 'object' && reply !== null) {
  reply = reply.text ?? JSON.stringify(reply);
}
reply = String(reply || '');

function extractJson(s) {
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start === -1 || end === -1 || end < start) return null;
  try { return JSON.parse(s.slice(start, end + 1)); } catch { return null; }
}

let out = extractJson(reply);
if (!out || typeof out.status !== 'string') {
  out = { status: 'error', message: `Không parse được JSON từ agent: ${reply.slice(0, 300)}` };
}
if (!['ok', 'checkpoint', 'error'].includes(out.status)) out.status = 'error';

return [{ json: out }];
